### 3. CODIFICAÇÃO EM C

```c
#include <stdio.h>
#include <stdlib.h>

#define MAX_TIPO 100
#define INF 1000000000

// Função de comparação para o qsort (ordem crescente)
int comparar_inteiros(const void *a, const void *b) {
    int x = *(const int *)a;
    int y = *(const int *)b;
    return (x - y);
}

int main(void) {
    int R, N;
    if (scanf("%d %d", &R, &N) != 2) {
        return 0;
    }

    // min_preco[t] armazenará o menor preço encontrado para a fruta do tipo t
    int min_preco[MAX_TIPO + 1];
    for (int i = 1; i <= MAX_TIPO; i++) {
        min_preco[i] = INF;
    }

    for (int i = 0; i < N; i++) {
        int tipo, preco;
        scanf("%d %d", &tipo, &preco);
        if (preco < min_preco[tipo]) {
            min_preco[tipo] = preco;
        }
    }

    // Coleta o menor preço de cada tipo único disponível
    int precos_disponiveis[MAX_TIPO + 1];
    int total_tipos = 0;

    for (int i = 1; i <= MAX_TIPO; i++) {
        if (min_preco[i] != INF) {
            precos_disponiveis[total_tipos++] = min_preco[i];
        }
    }

    // Ordena os custos em ordem crescente
    qsort(precos_disponiveis, total_tipos, sizeof(int), comparar_inteiros);

    // Abordagem gulosa: compra as frutas mais baratas primeiro
    int tipos_comprados = 0;
    for (int i = 0; i < total_tipos; i++) {
        if (R >= precos_disponiveis[i]) {
            R -= precos_disponiveis[i];
            tipos_comprados++;
        } else {
            break;
        }
    }

    printf("%d\n", tipos_comprados);

    return 0;
}
```

